import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Ge.css";

function Generate() {
  const canvasRef = useRef();
  const compositeCanvasRef = useRef(null);
  const gridDataRef = useRef([]);

  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [currentView, setCurrentView] = useState('final');

  const [effects, setEffects] = useState({
    grain: { intensity: 5, gamma: 1.2 },
    scanlines: { gap: 2, alpha: 0.1 },
    glitch: { lineHeight: 2, shiftAmount: 0 },
    saturation: { value: 0 }
  });

  const animationRef = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]");
    if (!stored.length) {
      navigate("/");
      return;
    }
    setImagePaths(stored);
    initializeGeneration(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  useEffect(() => {
    if (compositeCanvasRef.current && gridDataRef.current.length > 0) {
      drawCurrentView();
    }
  }, [currentView, effects]);

  // --- [Data Analysis Algorithm] ---
  const analyzeImageStatistics = (width, height, sourceCanvas) => {
    const ctx = sourceCanvas.getContext('2d');
    const gridSize = 20; 
    const cols = Math.ceil(width / gridSize);
    const rows = Math.ceil(height / gridSize);
    const analyzedData = [];

    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const posX = x * gridSize;
        const posY = y * gridSize;

        const imgData = ctx.getImageData(posX, posY, gridSize, gridSize);
        const data = imgData.data;

        let rSum=0, gSum=0, bSum=0, totalLum=0;
        const pixels = [];

        for(let i=0; i<data.length; i+=4) {
            const r = data[i];
            const g = data[i+1];
            const b = data[i+2];
            const lum = 0.299*r + 0.587*g + 0.114*b;
            rSum += r; gSum += g; bSum += b;
            totalLum += lum;
            pixels.push(lum);
        }

        const count = pixels.length;
        const avgLum = totalLum / count;

        let varianceSum = 0;
        for(let i=0; i<pixels.length; i++) {
            varianceSum += Math.pow(pixels[i] - avgLum, 2);
        }
        const variance = Math.sqrt(varianceSum / count);

        analyzedData.push({
            x: posX, y: posY, w: gridSize, h: gridSize,
            avgLum,
            variance,
            avgR: rSum / count,
            avgG: gSum / count,
            avgB: bSum / count,
            col: x, row: y
        });
      }
    }
    return analyzedData;
  };

  // --- [Layer Drawing Functions] ---

  const drawLayerVariance = (ctx, width, height) => {
    const data = gridDataRef.current;
    ctx.strokeStyle = "rgba(0, 255, 240, 0.25)";
    ctx.lineWidth = 1;

    data.forEach(cell => {
        if (cell.variance > 40) {
            ctx.strokeRect(cell.x, cell.y, cell.w, cell.h);
            ctx.beginPath();
            ctx.moveTo(cell.x, cell.y); ctx.lineTo(cell.x + cell.w, cell.y + cell.h);
            ctx.moveTo(cell.x + cell.w, cell.y); ctx.lineTo(cell.x, cell.y + cell.h);
            ctx.stroke();
        } else if (cell.variance > 15) {
            ctx.strokeRect(cell.x, cell.y, cell.w, cell.h);
        } else {
            ctx.fillStyle = "rgba(0, 255, 240, 0.1)";
            ctx.fillRect(cell.x + cell.w/2 - 1, cell.y + cell.h/2 - 1, 2, 2);
        }
    });
    drawLabel(ctx, 20, 30, "LAYER 01: SPATIAL VARIANCE (STRUCTURE)");
  };

  const drawLayerSpectral = (ctx, width, height) => {
    const data = gridDataRef.current;
    data.forEach(cell => {
        if (cell.avgLum < 10) return;
        const pad = 4;
        const barW = (cell.w - pad * 2) / 3;
        const maxH = cell.h - pad * 2;
        const hR = (cell.avgR / 255) * maxH;
        const hG = (cell.avgG / 255) * maxH;
        const hB = (cell.avgB / 255) * maxH;
        const baseX = cell.x + pad;
        const baseY = cell.y + cell.h - pad;

        ctx.fillStyle = "rgba(255, 50, 50, 0.8)";
        ctx.fillRect(baseX, baseY - hR, barW - 1, hR);
        ctx.fillStyle = "rgba(50, 255, 50, 0.8)";
        ctx.fillRect(baseX + barW, baseY - hG, barW - 1, hG);
        ctx.fillStyle = "rgba(50, 100, 255, 0.8)";
        ctx.fillRect(baseX + barW * 2, baseY - hB, barW - 1, hB);
    });
    drawLabel(ctx, 20, 30, "LAYER 02: SPECTRAL ANALYSIS (COLOR DATA)");
  };

  // [핵심 변경] Layer 3: 대각선만 허용하는 와이어프레임
  const drawLayerWireframe = (ctx, width, height) => {
    const data = gridDataRef.current;
    const gridSize = 20;

    ctx.lineWidth = 0.6;

    // 의미 있는 노드 필터링
    const nodes = data.filter(cell => cell.avgLum > 30 && cell.variance > 5);

    nodes.forEach((node, i) => {
        const cx = node.x + node.w / 2;
        const cy = node.y + node.h / 2;

        let connectedCount = 0;
        const maxConnections = 4; 
        const searchRadius = gridSize * 5; // 검색 반경

        // 주변 노드 탐색
        for (let j = i + 1; j < nodes.length; j++) {
            const neighbor = nodes[j];

            const dx = cx - (neighbor.x + neighbor.w/2);
            const dy = cy - (neighbor.y + neighbor.h/2);
            const distSq = dx*dx + dy*dy;

            // 1. 거리 제한
            if (distSq > searchRadius * searchRadius) continue;

            // [NEW] 2. 수직/수평 라인 제거 필터
            // dx나 dy가 0에 가까우면(2px 이내) 그리지 않음 -> 대각선만 남음
            if (Math.abs(dx) < 2 || Math.abs(dy) < 2) continue;

            // 3. 유사성 판단 (비슷한 밝기끼리만 연결)
            if (Math.abs(node.avgLum - neighbor.avgLum) > 50) continue;

            // 연결 그리기
            ctx.beginPath();
            ctx.moveTo(cx, cy);
            ctx.lineTo(neighbor.x + neighbor.w/2, neighbor.y + neighbor.h/2);

            const alpha = (1 - Math.sqrt(distSq) / searchRadius) * (node.avgLum / 255);
            ctx.strokeStyle = `rgba(255, 255, 255, ${alpha * 0.9})`;
            ctx.stroke();

            connectedCount++;
            if (connectedCount >= maxConnections) break;
        }

        // 노드 포인트
        if (connectedCount > 0) {
            ctx.fillStyle = "rgba(255, 255, 255, 0.9)";
            const pointSize = Math.min(3, node.variance / 10);
            ctx.fillRect(cx - pointSize/2, cy - pointSize/2, pointSize, pointSize);
        }
    });

    drawLabel(ctx, 20, 30, "LAYER 03: STRUCTURAL WIREFRAME (DIAGONAL ONLY)");
  };

  // Final Synthesis
  const drawFinal = (ctx, width, height) => {
    ctx.fillStyle = "#050a14"; 
    ctx.fillRect(0, 0, width, height);

    ctx.save();
    ctx.strokeStyle = "rgba(0, 255, 240, 0.15)";
    ctx.fillStyle = "rgba(0, 255, 240, 0.15)";
    drawLayerVariance(ctx, width, height); 
    ctx.restore();

    ctx.globalCompositeOperation = 'screen'; 
    drawLayerSpectral(ctx, width, height);

    ctx.globalCompositeOperation = 'source-over';
    ctx.strokeStyle = "rgba(255, 255, 255, 0.4)";
    drawLayerWireframe(ctx, width, height);

    drawGridOverlay(ctx, width, height);
    drawLabel(ctx, 20, 30, "FINAL SYNTHESIS: DIAGONAL STRUCTURAL ANALYSIS");
  };

  // --- [Helper: UI & Draw] ---
  const drawLabel = (ctx, x, y, text) => {
    ctx.font = "14px 'Courier New', monospace";
    ctx.fillStyle = "#fff";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(text, x, y);
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x, y + 20); ctx.lineTo(x + 300, y + 20); ctx.stroke();
  };

  const drawGridOverlay = (ctx, w, h) => {
    ctx.strokeStyle = "rgba(255,255,255,0.1)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(w/2, 0); ctx.lineTo(w/2, h);
    ctx.moveTo(0, h/2); ctx.lineTo(w, h/2);
    ctx.stroke();
    ctx.strokeRect(10, 10, w-20, h-20);
  };

  const initializeGeneration = (imagePaths) => {
    const canvas = canvasRef.current;
    const width = canvas.width;
    const height = canvas.height;

    const loadImage = (src) => new Promise((resolve) => {
        const img = new Image(); img.crossOrigin = "Anonymous"; img.onload = () => resolve(img); img.src = src;
    });

    Promise.all(imagePaths.map(loadImage)).then((images) => {
      const compositeCanvas = document.createElement('canvas');
      compositeCanvas.width = width; compositeCanvas.height = height;
      const compositeCtx = compositeCanvas.getContext('2d');
      compositeCtx.fillStyle = "#000"; compositeCtx.fillRect(0, 0, width, height);

      images.forEach((img, i) => { 
          if(i===0) compositeCtx.drawImage(img, 0, 0, width, height);
          else {
             compositeCtx.globalCompositeOperation = 'screen';
             compositeCtx.drawImage(img, 0, 0, width, height);
          }
      });
      compositeCanvasRef.current = compositeCanvas;
      gridDataRef.current = analyzeImageStatistics(width, height, compositeCanvas);
      drawCurrentView();
    });
  };

  const drawCurrentView = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.fillStyle = "#050505";
    ctx.fillRect(0, 0, width, height);

    switch (currentView) {
        case 'source':
            ctx.drawImage(compositeCanvasRef.current, 0, 0, width, height);
            drawLabel(ctx, 20, 30, "SOURCE INPUT DATA");
            break;
        case 'layer1':
            drawLayerVariance(ctx, width, height);
            break;
        case 'layer2':
            drawLayerSpectral(ctx, width, height);
            break;
        case 'layer3':
            drawLayerWireframe(ctx, width, height);
            break;
        case 'final':
        default:
            drawFinal(ctx, width, height);
    }

    applyScanlines(ctx, width, height);
    generateGrain(ctx, width, height);
  };

  const generateGrain = (ctx, w, h) => {
      if(effects.grain.intensity <= 0) return;
      const id = ctx.getImageData(0,0,w,h); const d = id.data;
      for(let i=0; i<d.length; i+=4) {
          const n = (Math.random()-0.5) * effects.grain.intensity;
          d[i]+=n; d[i+1]+=n; d[i+2]+=n;
      }
      ctx.putImageData(id, 0, 0);
  };
  const applyScanlines = (ctx, w, h) => {
      ctx.fillStyle = `rgba(0,0,0,${effects.scanlines.alpha})`;
      for(let y=0; y<h; y+=effects.scanlines.gap) ctx.fillRect(0,y,w,1);
  };

  const handleDownload = () => {
    const link = document.createElement("a");
    link.download = `analysis_${currentView}.png`;
    link.href = canvasRef.current.toDataURL("image/png");
    link.click();
  };
  const handleRegenerate = () => { initializeGeneration(imagePaths); };
  const handleBack = () => { navigate("/"); };

  return (
    <div className="ge-container">
      <div className="ge-title-container">
        <img src="/images/logo.gif" alt="Graphic Archive" style={{ height: '60px', width: 'auto', objectFit: 'contain' }} />
      </div>

      <div className="ge-main">
        <div className="ge-box1">
          <div className="ge-effects-panel">
            <div style={{ marginBottom: '20px' }}>
                <h3 style={{ margin: "0 0 10px 0", fontSize: "16px", fontWeight: "500", fontFamily: "monospace" }}>ANALYSIS LAYERS</h3>
                <div className="ge-layer-buttons">
                    <button className={`ge-layer-btn ${currentView === 'layer1' ? 'active' : ''}`} onClick={() => setCurrentView('layer1')}>1. VARIANCE</button>
                    <button className={`ge-layer-btn ${currentView === 'layer2' ? 'active' : ''}`} onClick={() => setCurrentView('layer2')}>2. SPECTRAL</button>
                    <button className={`ge-layer-btn ${currentView === 'layer3' ? 'active' : ''}`} onClick={() => setCurrentView('layer3')}>3. WIREFRAME</button>
                    <button className={`ge-layer-btn final ${currentView === 'final' ? 'active' : ''}`} onClick={() => setCurrentView('final')}>FINAL SYNTHESIS</button>
                </div>
            </div>

            <h3 style={{ margin: "0 0 15px 0", fontSize: "16px", fontWeight: "500", fontFamily: "monospace" }}>DISPLAY PARAMS</h3>
            <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
              <div>
                <label style={{ fontSize: "12px", fontFamily: "monospace" }}>NOISE_LEVEL: {effects.grain.intensity}</label>
                <input type="range" min="0" max="50" step="5" value={effects.grain.intensity} onChange={(e) => setEffects(p => ({...p, grain: {...p.grain, intensity: Number(e.target.value)}}))} style={{ width: "100%" }} />
              </div>
            </div>
          </div>

          <div className="ge-button-container">
            <button onClick={handleBack} className="ge-button ge-button-back">BACK</button>
            <button onClick={handleRegenerate} className="ge-button ge-button-regenerate">RE-ANALYZE</button>
            <button onClick={handleDownload} className="ge-button ge-button-download">EXPORT DATA</button>
          </div>
        </div>

        <div className="ge-canvas-container">
          <canvas ref={canvasRef} width={1080} height={1080} className="ge-canvas" />
        </div>
      </div>
    </div>
  );
}

export default Generate;
